use vstd::prelude::*;

verus! {

fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
    ensures
        // Exactly one row
        result.len() == 1,
        // The single row has the same length as the input
        result[0].len() == arr.len(),
        // Elementwise equality (order preserved)
        forall|i: int|
            0 <= i < arr.len() ==> result[0][i] == arr[i],
{
    // Build the single row by copying arr element-by-element
    let mut row: Vec<f32> = Vec::new();
    let mut i: usize = 0;

    while i < arr.len()
        invariant
            i <= arr.len(),
            row.len() == i,
            forall|j: int| 0 <= j < i ==> row[j] == arr[j],
        decreases arr.len() - i,
    {
        row.push(arr[i]);
        i += 1;
    }

    // Put the row into a 2D array with exactly one row
    let mut result: Vec<Vec<f32>> = Vec::new();
    result.push(row);

    result
}

} // verus!

